import React, { useState, useEffect, useCallback } from 'react';
import { MapContainer, TileLayer, Marker, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import styles from './LocationPicker.module.css';

// Fix default marker icon broken by webpack
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

function DraggableMarker({ position, onMove }) {
  useMapEvents({
    click(e) { onMove(e.latlng); }
  });
  return position ? <Marker position={position} draggable eventHandlers={{ dragend: (e) => onMove(e.target.getLatLng()) }} /> : null;
}

async function reverseGeocode(lat, lng) {
  const res = await fetch(
    `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`,
    { headers: { 'Accept-Language': 'en' } }
  );
  const data = await res.json();
  const addr = data.address || {};
  return {
    lat, lng,
    address: [addr.house_number, addr.road, addr.suburb || addr.neighbourhood,
      addr.city || addr.town || addr.village, addr.state, addr.postcode
    ].filter(Boolean).join(', ') || data.display_name,
    city: addr.city || addr.town || addr.village || '',
    postcode: addr.postcode || ''
  };
}

export default function LocationPicker({ initialLocation, onConfirm, onClose }) {
  const defaultPos = initialLocation
    ? { lat: initialLocation.lat, lng: initialLocation.lng }
    : { lat: 40.7128, lng: -74.006 }; // NYC default

  const [markerPos, setMarkerPos] = useState(defaultPos);
  const [resolvedAddress, setResolvedAddress] = useState(initialLocation?.address || '');
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);

  const handleMove = useCallback(async (latlng) => {
    setMarkerPos(latlng);
    setLoading(true);
    try {
      const loc = await reverseGeocode(latlng.lat, latlng.lng);
      setResolvedAddress(loc.address);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    const res = await fetch(
      `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(searchQuery)}&format=json&limit=5`,
      { headers: { 'Accept-Language': 'en' } }
    );
    const data = await res.json();
    setSearchResults(data);
  };

  const selectSearchResult = async (result) => {
    const lat = parseFloat(result.lat);
    const lng = parseFloat(result.lon);
    setMarkerPos({ lat, lng });
    setResolvedAddress(result.display_name);
    setSearchResults([]);
    setSearchQuery('');
  };

  const handleConfirm = async () => {
    setLoading(true);
    try {
      const loc = await reverseGeocode(markerPos.lat, markerPos.lng);
      onConfirm(loc);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.overlay}>
      <div className={styles.modal}>
        <div className={styles.header}>
          <h3>📍 Set Delivery Location</h3>
          <button className={styles.closeBtn} onClick={onClose}>✕</button>
        </div>

        <div className={styles.searchRow}>
          <input
            type="text"
            placeholder="Search for an address..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSearch()}
          />
          <button onClick={handleSearch}>Search</button>
        </div>

        {searchResults.length > 0 && (
          <ul className={styles.searchResults}>
            {searchResults.map((r, i) => (
              <li key={i} onClick={() => selectSearchResult(r)}>{r.display_name}</li>
            ))}
          </ul>
        )}

        <div className={styles.mapWrapper}>
          <MapContainer center={markerPos} zoom={14} style={{ height: '100%', width: '100%' }}>
            <TileLayer
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              attribution='© <a href="https://openstreetmap.org">OpenStreetMap</a>'
            />
            <DraggableMarker position={markerPos} onMove={handleMove} />
          </MapContainer>
        </div>

        <div className={styles.addressPreview}>
          <span>📍</span>
          <span>{loading ? 'Fetching address...' : resolvedAddress || 'Click on map to set location'}</span>
        </div>

        <button className={styles.confirmBtn} onClick={handleConfirm} disabled={loading || !resolvedAddress}>
          {loading ? 'Loading...' : 'Confirm Location'}
        </button>
      </div>
    </div>
  );
}
