import React, { useEffect, useState, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polyline, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { pushAgentLocation, listenToAgentLocation } from '../firebase/services';
import styles from './LiveTrackingMap.module.css';

// Fix default marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl:       'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl:     'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

// Custom colored icons
const makeIcon = (emoji, color) => L.divIcon({
  className: '',
  html: `<div style="
    background:${color};width:38px;height:38px;border-radius:50%;
    display:flex;align-items:center;justify-content:center;
    font-size:20px;border:3px solid #fff;
    box-shadow:0 2px 8px rgba(0,0,0,0.3);">${emoji}</div>`,
  iconSize: [38, 38],
  iconAnchor: [19, 19],
  popupAnchor: [0, -20],
});

const ICONS = {
  restaurant: makeIcon('🍽️', '#ff6b35'),
  customer:   makeIcon('🏠', '#3b82f6'),
  agent:      makeIcon('🛵', '#10b981'),
};

// Auto-fit map bounds to all markers
function FitBounds({ points }) {
  const map = useMap();
  useEffect(() => {
    if (points.length > 1) {
      const bounds = L.latLngBounds(points.map(p => [p.lat, p.lng]));
      map.fitBounds(bounds, { padding: [50, 50] });
    } else if (points.length === 1) {
      map.setView([points[0].lat, points[0].lng], 14);
    }
  }, [points, map]);
  return null;
}

// Animated agent marker that smoothly moves
function AnimatedAgentMarker({ position, icon }) {
  const markerRef = useRef(null);
  useEffect(() => {
    if (markerRef.current && position) {
      markerRef.current.setLatLng([position.lat, position.lng]);
    }
  }, [position]);
  if (!position?.lat) return null;
  return (
    <Marker ref={markerRef} position={[position.lat, position.lng]} icon={icon}>
      <Popup>🛵 Delivery Partner<br /><small>Live location</small></Popup>
    </Marker>
  );
}

export default function LiveTrackingMap({ orderId, role, agentId, onAgentLocationUpdate }) {
  const [tracking, setTracking] = useState(null);
  const [agentPos, setAgentPos] = useState(null);
  const watchRef = useRef(null);

  // Fetch tracking data from backend (restaurant/customer coords)
  useEffect(() => {
    if (!orderId) return;
    const fetch_ = () => {
      fetch(`/api/tracking/${orderId}`)
        .then(r => r.json())
        .then(data => { setTracking(data); })
        .catch(() => {});
    };
    fetch_();
    const interval = setInterval(fetch_, 10000);
    return () => clearInterval(interval);
  }, [orderId]);

  // Subscribe to agent location from Firebase Realtime DB
  useEffect(() => {
    if (!tracking?.agent?.id) return;
    const unsub = listenToAgentLocation(tracking.agent.id, (loc) => {
      setAgentPos({ lat: loc.lat, lng: loc.lng });
    });
    return unsub;
  }, [tracking?.agent?.id]);

  // Delivery agent: push live GPS to Firebase Realtime DB
  useEffect(() => {
    if (role !== 'delivery' || !agentId) return;
    const pushLocation = (pos) => {
      const { latitude: lat, longitude: lng } = pos.coords;
      setAgentPos({ lat, lng });
      pushAgentLocation(agentId, lat, lng).catch(() => {});
      if (onAgentLocationUpdate) onAgentLocationUpdate({ lat, lng });
    };
    if (navigator.geolocation) {
      watchRef.current = navigator.geolocation.watchPosition(pushLocation, () => {}, {
        enableHighAccuracy: true, maximumAge: 4000, timeout: 8000
      });
    }
    return () => {
      if (watchRef.current) navigator.geolocation.clearWatch(watchRef.current);
    };
  }, [role, agentId, onAgentLocationUpdate]);

  if (!tracking) return (
    <div className={styles.loading}>
      <div className={styles.spinner} />
      <p>Loading map...</p>
    </div>
  );

  const { restaurant, customer, agent, status } = tracking;

  const allPoints = [
    { lat: restaurant.lat, lng: restaurant.lng },
    { lat: customer.lat,   lng: customer.lng },
    ...(agentPos?.lat ? [{ lat: agentPos.lat, lng: agentPos.lng }] : []),
  ];

  const routeLine = agentPos?.lat
    ? [[restaurant.lat, restaurant.lng], [agentPos.lat, agentPos.lng], [customer.lat, customer.lng]]
    : [[restaurant.lat, restaurant.lng], [customer.lat, customer.lng]];

  const center = allPoints[0] || { lat: 19.0760, lng: 72.8777 };

  return (
    <div className={styles.wrapper}>
      {/* Legend */}
      <div className={styles.legend}>
        <span>🍽️ Restaurant</span>
        <span>🛵 Delivery Partner</span>
        <span>🏠 Customer</span>
        <span className={`${styles.statusChip} ${styles[status?.replace(/ /g,'')]}`}>{status}</span>
      </div>

      <MapContainer center={[center.lat, center.lng]} zoom={13} className={styles.map}>
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='© <a href="https://openstreetmap.org">OpenStreetMap</a>'
        />
        <FitBounds points={allPoints} />

        {/* Route line */}
        <Polyline
          positions={routeLine}
          pathOptions={{ color: '#ff6b35', weight: 4, dashArray: '8 6', opacity: 0.8 }}
        />

        {/* Restaurant marker */}
        <Marker position={[restaurant.lat, restaurant.lng]} icon={ICONS.restaurant}>
          <Popup>
            <strong>🍽️ {restaurant.name}</strong><br />
            <small>{restaurant.address}</small>
          </Popup>
        </Marker>

        {/* Customer marker */}
        <Marker position={[customer.lat, customer.lng]} icon={ICONS.customer}>
          <Popup>
            <strong>🏠 {customer.name}</strong><br />
            <small>{customer.address}</small>
          </Popup>
        </Marker>

        {/* Agent marker — animated */}
        <AnimatedAgentMarker position={agentPos} icon={ICONS.agent} />
      </MapContainer>

      {/* Info cards below map */}
      <div className={styles.infoRow}>
        <div className={styles.infoCard}>
          <span className={styles.infoIcon}>🍽️</span>
          <div>
            <p className={styles.infoLabel}>Restaurant</p>
            <p className={styles.infoVal}>{restaurant.name}</p>
            <p className={styles.infoAddr}>{restaurant.address}</p>
          </div>
        </div>
        {agent?.name && (
          <div className={styles.infoCard}>
            <span className={styles.infoIcon}>🛵</span>
            <div>
              <p className={styles.infoLabel}>Delivery Partner</p>
              <p className={styles.infoVal}>{agent.name}</p>
              <p className={styles.infoAddr}>
                {agentPos?.lat
                  ? `📍 Live: ${agentPos.lat.toFixed(4)}, ${agentPos.lng.toFixed(4)}`
                  : 'Location updating...'}
              </p>
            </div>
          </div>
        )}
        <div className={styles.infoCard}>
          <span className={styles.infoIcon}>🏠</span>
          <div>
            <p className={styles.infoLabel}>Delivery Address</p>
            <p className={styles.infoVal}>{customer.name}</p>
            <p className={styles.infoAddr}>{customer.address}</p>
          </div>
        </div>
      </div>
    </div>
  );
}
