import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../../context/AuthContext';
import ReviewSection from '../../components/ReviewSection';
import LiveTrackingMap from '../../components/LiveTrackingMap';
import { listenToOrdersByRestaurant, getRestaurant, updateOrderStatus, toggleRestaurantStatus, toggleMenuItemAvailability } from '../../firebase/services';
import styles from './Dashboard.module.css';

const STATUS_FLOW = ['Placed', 'Confirmed', 'Preparing', 'Out for Delivery', 'Delivered'];
const NEXT_ACTION = {
  'Placed':    { label: 'Accept Order',    next: 'Confirmed' },
  'Confirmed': { label: 'Start Preparing', next: 'Preparing' },
  'Preparing': { label: 'Ready for Pickup',next: 'Out for Delivery' },
};
const STATUS_COLOR = {
  'Placed':           '#dbeafe',
  'Confirmed':        '#fef3c7',
  'Preparing':        '#ede9fe',
  'Out for Delivery': '#ffedd5',
  'Delivered':        '#d1fae5',
};

export default function RestaurantDashboard() {
  const { user } = useAuth();
  const [tab, setTab] = useState('orders');
  const [orders, setOrders] = useState([]);
  const [restaurant, setRestaurant] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('active');
  const [trackingOrderId, setTrackingOrderId] = useState(null);

  const fetchData = useCallback(async () => {
    const restData = await getRestaurant(user.restaurantId);
    setRestaurant(restData);
    setLoading(false);
  }, [user.restaurantId]);

  useEffect(() => {
    fetchData();
    // Real-time orders listener
    const unsub = listenToOrdersByRestaurant(user.restaurantId, setOrders);
    return unsub;
  }, [fetchData, user.restaurantId]);

  const advanceStatus = async (orderId, nextStatus) => {
    await updateOrderStatus(orderId, nextStatus);
  };

  const toggleRestStatus = async () => {
    await toggleRestaurantStatus(user.restaurantId);
    fetchData();
  };

  const toggleMenuItem = async (itemId) => {
    await toggleMenuItemAvailability(user.restaurantId, itemId);
    fetchData();
  };

  if (loading) return <p className={styles.loading}>Loading dashboard...</p>;

  const activeOrders  = orders.filter(o => o.status !== 'Delivered');
  const pastOrders    = orders.filter(o => o.status === 'Delivered');
  const displayOrders = filter === 'active' ? activeOrders : pastOrders;

  const todayRevenue  = pastOrders.reduce((s, o) => s + o.total, 0);
  const totalOrders   = orders.length;

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.header}>
        <div>
          <h1>{restaurant.name}</h1>
          <p className={styles.address}>📍 {restaurant.address}</p>
        </div>
        <button
          className={`${styles.toggleBtn} ${restaurant.isOpen ? styles.open : styles.closed}`}
          onClick={toggleRestStatus}
        >
          {restaurant.isOpen ? '● Open — Click to Close' : '● Closed — Click to Open'}
        </button>
      </div>

      {/* Stats */}
      <div className={styles.stats}>
        <div className={styles.stat}>
          <span className={styles.statVal}>{activeOrders.length}</span>
          <span className={styles.statLabel}>Active Orders</span>
        </div>
        <div className={styles.stat}>
          <span className={styles.statVal}>{totalOrders}</span>
          <span className={styles.statLabel}>Total Orders</span>
        </div>
        <div className={styles.stat}>
          <span className={styles.statVal}>₹{todayRevenue.toFixed(0)}</span>
          <span className={styles.statLabel}>Revenue</span>
        </div>
        <div className={styles.stat}>
          <span className={styles.statVal}>⭐ {restaurant.rating}</span>
          <span className={styles.statLabel}>Rating</span>
        </div>
      </div>

      {/* Tabs */}
      <div className={styles.tabs}>
        <button className={`${styles.tab} ${tab === 'orders' ? styles.activeTab : ''}`} onClick={() => setTab('orders')}>
          Orders {activeOrders.length > 0 && <span className={styles.tabBadge}>{activeOrders.length}</span>}
        </button>
        <button className={`${styles.tab} ${tab === 'menu' ? styles.activeTab : ''}`} onClick={() => setTab('menu')}>
          Menu Management
        </button>
        <button className={`${styles.tab} ${tab === 'reviews' ? styles.activeTab : ''}`} onClick={() => setTab('reviews')}>
          Reviews ⭐
        </button>
      </div>

      {/* Orders Tab */}
      {tab === 'orders' && (
        <div>
          <div className={styles.filterRow}>
            <button className={`${styles.filterBtn} ${filter === 'active' ? styles.activeFilter : ''}`} onClick={() => setFilter('active')}>
              Active ({activeOrders.length})
            </button>
            <button className={`${styles.filterBtn} ${filter === 'past' ? styles.activeFilter : ''}`} onClick={() => setFilter('past')}>
              Completed ({pastOrders.length})
            </button>
          </div>

          {displayOrders.length === 0 ? (
            <div className={styles.empty}>
              <p>{filter === 'active' ? '🎉 No active orders right now' : '📦 No completed orders yet'}</p>
            </div>
          ) : (
            <div className={styles.orderGrid}>
              {displayOrders.map(order => {
                const action = NEXT_ACTION[order.status];
                return (
                  <div key={order.id} className={styles.orderCard} style={{ borderTop: `4px solid ${STATUS_COLOR[order.status] || '#eee'}` }}>
                    <div className={styles.orderHeader}>
                      <div>
                        <span className={styles.orderId}>#{order.id}</span>
                        <span className={styles.orderStatus} style={{ background: STATUS_COLOR[order.status] }}>
                          {order.status}
                        </span>
                      </div>
                      <span className={styles.orderTime}>{new Date(order.placedAt).toLocaleTimeString()}</span>
                    </div>

                    <div className={styles.customerRow}>
                      <span>👤 {order.customerName}</span>
                      <span className={styles.orderTotal}>₹{order.total.toFixed(0)}</span>
                    </div>

                    <div className={styles.orderItems}>
                      {order.items.map(item => (
                        <div key={item.id} className={styles.orderItem}>
                          <span>{item.name}</span>
                          <span>× {item.quantity}</span>
                        </div>
                      ))}
                    </div>

                    <p className={styles.deliveryAddr}>📍 {order.deliveryAddress}</p>

                    {action && (
                      <button className={styles.actionBtn} onClick={() => advanceStatus(order.id, action.next)}>
                        {action.label} →
                      </button>
                    )}
                    {order.status === 'Out for Delivery' && (
                      <button className={styles.trackBtn} onClick={() => setTrackingOrderId(order.id)}>
                        📍 Track Live
                      </button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Menu Tab */}
      {tab === 'menu' && (
        <div className={styles.menuSection}>
          <p className={styles.menuHint}>Toggle items to mark them as available or unavailable.</p>
          {['Pizza', 'Pasta', 'Salads', 'Sides', 'Dessert'].map(cat => {
            const catItems = restaurant.menu.filter(i => i.category === cat);
            if (!catItems.length) return null;
            return (
              <div key={cat} className={styles.menuCategory}>
                <h4>{cat}</h4>
                {catItems.map(item => (
                  <div key={item.id} className={`${styles.menuItem} ${!item.available ? styles.unavailable : ''}`}>
                    <img src={item.image} alt={item.name} />
                    <div className={styles.menuItemInfo}>
                      <span className={styles.menuItemName}>{item.name}</span>
                      <span className={styles.menuItemPrice}>₹{item.price.toFixed(0)}</span>
                    </div>
                    <button
                      className={`${styles.toggleAvail} ${item.available ? styles.availOn : styles.availOff}`}
                      onClick={() => toggleMenuItem(item.id)}
                    >
                      {item.available ? 'Available' : 'Unavailable'}
                    </button>
                  </div>
                ))}
              </div>
            );
          })}
        </div>
      )}

      {/* Reviews Tab */}
      {tab === 'reviews' && (
        <div className={styles.reviewsTab}>
          <ReviewSection restaurantId={user.restaurantId} />
        </div>
      )}

      {/* Live Tracking Modal */}
      {trackingOrderId && (
        <div className={styles.trackingOverlay}>
          <div className={styles.trackingModal}>
            <div className={styles.trackingHeader}>
              <h3>📍 Live Order Tracking — #{trackingOrderId}</h3>
              <button onClick={() => setTrackingOrderId(null)}>✕</button>
            </div>
            <LiveTrackingMap orderId={trackingOrderId} role="restaurant" />
          </div>
        </div>
      )}
    </div>
  );
}
