import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import styles from './Login.module.css';

const DEMO_ACCOUNTS = [
  { label: '👩 Customer',     email: 'customer@demo.com',  role: 'customer' },
  { label: '🍕 Restaurant',   email: 'owner@demo.com',     role: 'restaurant' },
  { label: '🚴 Delivery',     email: 'delivery@demo.com',  role: 'delivery' },
];

export default function Login() {
  const { login } = useAuth();
  const [form, setForm] = useState({ email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true); setError('');
    try { await login(form.email, form.password); }
    catch (err) { setError(err.message); }
    finally { setLoading(false); }
  };

  const quickLogin = async (email) => {
    setLoading(true); setError('');
    try { await login(email, 'password123'); }
    catch (err) { setError(err.message); }
    finally { setLoading(false); }
  };

  return (
    <div className={styles.page}>
      <div className={styles.card}>
        <div className={styles.brand}>🍔 FoodDash</div>
        <h2>Welcome back</h2>
        <p className={styles.sub}>Sign in to continue</p>

        <div className={styles.demoSection}>
          <p className={styles.demoLabel}>Quick demo login</p>
          <div className={styles.demoButtons}>
            {DEMO_ACCOUNTS.map(a => (
              <button key={a.email} className={styles.demoBtn} onClick={() => quickLogin(a.email)} disabled={loading}>
                {a.label}
              </button>
            ))}
          </div>
        </div>

        <div className={styles.divider}><span>or sign in manually</span></div>

        <form onSubmit={handleSubmit} className={styles.form}>
          <label>Email
            <input type="email" required placeholder="you@example.com"
              value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} />
          </label>
          <label>Password
            <input type="password" required placeholder="••••••••"
              value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} />
          </label>
          {error && <p className={styles.error}>⚠ {error}</p>}
          <button type="submit" className={styles.submitBtn} disabled={loading}>
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        <div className={styles.hint}>
          <strong>Demo password for all accounts:</strong> password123
        </div>
      </div>
    </div>
  );
}
